<style>
    .success-page-center{
        min-height:70vh;
        display:flex;
        align-items:flex-start;
        justify-content:center;
        padding:80px 18px 30px;
        background:transparent;
        position:relative;
        overflow:hidden;
        box-sizing:border-box;
    }

    .success-page-center::after{
        content:"";
        position:absolute;
        top:35px;
        right:-70px;
        width:180px;
        height:260px;
        background:linear-gradient(180deg,#87a2ff 0%,#6e8fff 100%);
        clip-path:polygon(35% 0,100% 0,100% 100%,0 50%);
        opacity:.9;
        pointer-events:none;
    }

    .success-card{
        width:100%;
        max-width:560px;
        background:#ffffff;
        border-radius:20px;
        padding:38px 30px;
        box-shadow:0 10px 35px rgba(0,0,0,0.08);
        position:relative;
        z-index:2;
        text-align:center;
        box-sizing:border-box;
    }

    .success-content{
        width:100%;
        display:flex;
        flex-direction:column;
        align-items:center;
    }

    .success-icon{
        width:78px;
        height:78px;
        display:flex;
        align-items:center;
        justify-content:center;
        border-radius:50%;
        background:#eef8f2;
        margin-bottom:20px;
        flex-shrink:0;
    }

    .success-icon svg{
        width:42px;
        height:42px;
        display:block;
    }

    .success-title{
        font-size:32px;
        line-height:1.2;
        font-weight:700;
        color:#000;
        margin-bottom:14px;
    }

    .success-description{
        width:100%;
        max-width:430px;
        font-size:17px;
        line-height:1.65;
        color:#2f2f2f;
        margin-bottom:20px;
    }

    .success-status{
        display:inline-flex;
        align-items:center;
        justify-content:center;
        gap:9px;
        padding:10px 17px;
        border-radius:999px;
        background:#f4fbf6;
        border:1px solid #d7ebde;
        margin-bottom:18px;
        max-width:100%;
        box-sizing:border-box;
    }

    .success-status-dot{
        width:9px;
        height:9px;
        border-radius:50%;
        background:#2f7d57;
        display:inline-block;
        flex-shrink:0;
    }

    .success-status-text{
        font-size:15px;
        font-weight:600;
        color:#2f7d57;
    }

    .success-note{
        font-size:16px;
        line-height:1.55;
        color:#444;
    }

    @media (max-width:768px){
        .success-page-center{
            padding:55px 16px 25px;
        }

        .success-page-center::after{
            width:130px;
            height:200px;
            right:-55px;
            top:20px;
        }

        .success-card{
            max-width:520px;
            padding:32px 24px;
            border-radius:18px;
        }

        .success-title{
            font-size:28px;
        }

        .success-description{
            font-size:16px;
        }
    }

    @media (max-width:480px){
        .success-page-center{
            min-height:auto;
            padding:38px 14px 24px;
        }

        .success-page-center::after{
            width:95px;
            height:155px;
            right:-42px;
            top:12px;
        }

        .success-card{
            padding:27px 18px;
            border-radius:16px;
        }

        .success-icon{
            width:68px;
            height:68px;
            margin-bottom:17px;
        }

        .success-icon svg{
            width:36px;
            height:36px;
        }

        .success-title{
            font-size:25px;
            margin-bottom:12px;
        }

        .success-description{
            font-size:15px;
            line-height:1.6;
            margin-bottom:18px;
        }

        .success-status{
            padding:9px 14px;
        }

        .success-status-text{
            font-size:14px;
        }

        .success-note{
            font-size:14px;
        }
    }
</style>

